LINE_FIELDS = ("op", "value", "radius", "ripe", "caller", "block", "new", "party", "alt", "label", "meta")   # 0.3.3: + alt, label; 0.4.4: + meta


def line_text(lid, name, mode, auto, hide, tasks, head, order=None, area="", short_after=""):
    out = ["# " + h for h in head]
    out += ["line=" + lid, "name=" + name, "mode=" + mode, "auto=" + ("true" if auto else "false")]
    if order is not None:
        out.append("order=%d" % order)
    if area:
        out.append("area=" + area)
    if hide:
        out.append("hide.setting=" + hide)
    if short_after:
        out.append("short.after=" + short_after)
    for n, (tid, tn, wh, hint, rew, anyp, parts, req, fl) in enumerate(tasks, 1):
        out.append("")
        p = "task.%d." % n
        out += [p + "id=" + tid, p + "name=" + tn]
        if wh:
            out.append(p + "where=" + wh)
        out.append(p + "hint=" + hint)
        out.append(p + "reward=" + rew)
        if req:
            out.append(p + "requires=" + req)
        if anyp:
            out.append(p + "any=true")
        for k in ("optional", "island", "tut", "was", "was.reward"):          # 0.3.3: + was, was.reward
            if k in fl:
                out.append(p + k + "=" + fl[k])
        pre = [p] if len(parts) == 1 else [p + "p%d." % (k + 1) for k in range(len(parts))]
        for pp, (ty, mt, cnt, ex) in zip(pre, parts):
            out += [pp + "type=" + ty, pp + "match=" + mt]
            if cnt != 1:
                out.append(pp + "count=%d" % cnt)
            for k in LINE_FIELDS:
                if k in ex:
                    out.append(pp + k + "=" + ex[k])
    return "\n".join(out) + "\n"


