# "<coins>,<Skill:N or empty>" -> { coins, xp } or null (a bad line is ignored, the quest file's reward stays)
M(cfg, r"""
public static String[] parseReward(String v) {
  if (v == null) return null;
  String s = v.trim();
  int c = s.indexOf(',');
  String a = c < 0 ? s : s.substring(0, c).trim();
  String b = c < 0 ? "" : s.substring(c + 1).trim();
  long n = @PKG@.QLog.num(a, -1L);
  if (n < 0L || n > 100000L) return null;
  if (b.length() > 0) {
    int k = b.indexOf(':');
    if (k <= 0) return null;
    long x = @PKG@.QLog.num(b.substring(k + 1), -1L);
    if (x < 0L || x > 100000L) return null;
  }
  return new String[] { String.valueOf(n), b };
}""")
# the whole file -> the fields (missing key = its default, out of range = clamped) + the tutorial.reward.* table (task id ->
# String[] { coins, "Skill:N" or "" }). Writes the default file when there is none (setup thread, never a world thread).
M(cfg, r"""
public static void load() {
  try {
    if (FILE == null) return;
    java.util.Properties p = @PKG@.QLog.readProps(FILE);
    if (p == null) {
      @PKG@.QLog.writeAtomic(FILE, DEFAULT_TEXT);
      p = new java.util.Properties();
      p.load(new java.io.StringReader(DEFAULT_TEXT));
    }
    ENABLED = @PKG@.QLog.bool(p.getProperty("enabled"), true);
    TUT_ON = @PKG@.QLog.bool(p.getProperty("tutorial.enabled"), true);
    WELCOME = @PKG@.QLog.bool(p.getProperty("tutorial.welcome"), true);
    TASKS = clampI(@PKG@.QLog.num(p.getProperty("widget.tasks"), 3L), 1, 3);
    double d = @PKG@.QLog.dec(p.getProperty("widget.doneSeconds"), 2.5);
    DONE_SECS = d < 0.0 ? 0.0 : (d > 10.0 ? 10.0 : d);
    POLL_SECS = clampI(@PKG@.QLog.num(p.getProperty("poll.seconds"), 1L), 1, 10);
    LAZY_SECS = clampI(@PKG@.QLog.num(p.getProperty("lazy.seconds"), 5L), 2, 60);
    RETRY_SECS = clampI(@PKG@.QLog.num(p.getProperty("claim.retrySeconds"), 60L), 30, 600);
    EVENT_RATE = clampI(@PKG@.QLog.num(p.getProperty("event.rate"), 20L), 1, 100);
    FOLLOW = @PKG@.QLog.bool(p.getProperty("areas.follow"), true);              // 0.2: the widget follows the area you enter
    PARTY_KILLS = @PKG@.QLog.bool(p.getProperty("coop.partyKills"), true);      // 0.2: party=true kill parts credit the party
    String mn = p.getProperty("markers.npc", "both").trim().toLowerCase(java.util.Locale.ROOT);         // 0.3
    MARK_NPC = (mn.equals("off") || mn.equals("prop") || mn.equals("particle") || mn.equals("both")) ? mn : "both";
    MARK_MAP = @PKG@.QLog.bool(p.getProperty("markers.map"), true);
    BOARD_ON = @PKG@.QLog.bool(p.getProperty("board.enabled"), true);
    BOARD_ANCHOR = clampI(@PKG@.QLog.num(p.getProperty("board.anchorSeconds"), 0L), 0, 86399);
    BOARD_REMOTE = @PKG@.QLog.bool(p.getProperty("board.remote"), false);
    BOARD_JOBS = clampI(@PKG@.QLog.num(p.getProperty("board.jobsPerDay"), 3L), 1, 3);              // FIX C3: 1 Easy / 2 + Medium / 3 + Hard
    BOARD_SCALE = clampI(@PKG@.QLog.num(p.getProperty("board.coinScalePercent"), 100L), 0, 300);   // FIX C3: board coins x percent
    SND_ON = @PKG@.QLog.bool(p.getProperty("sounds.enabled"), true);                 // 0.3.1 sound pass
    SND_TASK = @PKG@.QLog.bool(p.getProperty("sound.task"), true);
    SND_TASK_ID = p.getProperty("sound.task.id", "SFX_Dungeon_Checkpoint_Activate").trim();
    SND_QUEST = @PKG@.QLog.bool(p.getProperty("sound.quest"), true);
    SND_QUEST_ID = p.getProperty("sound.quest.id", "SFX_Event_Chapter_1_Complete_Sting").trim();
    SND_REWARD = @PKG@.QLog.bool(p.getProperty("sound.reward"), true);
    SND_REWARD_ID = p.getProperty("sound.reward.id", "SFX_Coins_Land").trim();
    SND_TALK = @PKG@.QLog.bool(p.getProperty("sound.talk"), true);
    SND_TALK_ID = p.getProperty("sound.talk.id", "SFX_Drag_Items_Paper").trim();
    GEAR_ARM = p.getProperty("gear.classArmor", "@GEARARM@").trim();          // 0.4.1 quest gear (absent = the default)
    GEAR_SEC = p.getProperty("gear.classSecond", "@GEARSEC@").trim();
    GEAR_NOBAG = p.getProperty("gear.noBagWeapon", "@GEARNB@").trim();
    java.util.HashMap rw = new java.util.HashMap();
    java.util.Iterator it = p.stringPropertyNames().iterator();
    while (it.hasNext()) {
      String k = (String) it.next();
      if (!k.startsWith("tutorial.reward.")) continue;
      String[] r = parseReward(p.getProperty(k));
      if (r != null) rw.put(k.substring("tutorial.reward.".length()), r);
      else @PKG@.QLog.warn("config.properties: " + k + "=" + p.getProperty(k) + " is not <coins>,<Skill>:<XP> - the quest file's reward is used");
    }
    REWARDS = rw;
  } catch (Throwable t) { @PKG@.QLog.warn("could not read config.properties (the defaults stay): " + t); }
}""")

# =====================================================================================================================
# 0.3.1 QSnd: the ONE sound helper (research/Sound-Pass-Plan.md section 1, the SkyyExploration 0.2.7 recipe). 2D to one player, category UI
# (SoundUtil.playSoundEvent2dToPlayer: one PlaySoundEvent2D packet to that player's connection). Never throws. pick() = the configured id
# when the master switch and that sound are on (else null = silent); the id is looked up in the game's SoundEvent map each time (a map
# lookup; a missing id = one WARN per id, nothing played); at most one of the same sound per player per GAP_MS (a burst = one sting).
# check() = the Server Setup check= hook of the id rows.
# =====================================================================================================================
qsnd = K("QSnd")
F(qsnd, "public static final java.util.concurrent.ConcurrentHashMap LAST = new java.util.concurrent.ConcurrentHashMap();")
F(qsnd, "public static final java.util.concurrent.ConcurrentHashMap WARNED = new java.util.concurrent.ConcurrentHashMap();")
F(qsnd, "public static final java.util.concurrent.atomic.AtomicLong PLAYED = new java.util.concurrent.atomic.AtomicLong();")
F(qsnd, "public static final long GAP_MS = 500L;")
M(qsnd, r"""
public static int idx(String id) {
  if (id == null) return Integer.MIN_VALUE;
  String v = id.trim();
  if (v.length() == 0) return Integer.MIN_VALUE;
  try {
    com.hypixel.hytale.assetstore.map.IndexedLookupTableAssetMap m = com.hypixel.hytale.server.core.asset.type.soundevent.config.SoundEvent.getAssetMap();
    return m == null ? Integer.MIN_VALUE : m.getIndex(v);
  } catch (Throwable t) { return Integer.MIN_VALUE; }
}""")
M(qsnd, r"""
public static String err(String value) {
  if (value == null) return null;
  String v = value.trim();
  if (v.length() == 0) return null;
  if (v.length() > 120) return "A sound id is at most 120 characters.";
  for (int i = 0; i < v.length(); i++) {
    char c = v.charAt(i);
    if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_')) return "A sound id is letters, digits and _ only (like SFX_Coins_Land).";
  }
  try {
    com.hypixel.hytale.assetstore.map.IndexedLookupTableAssetMap m = com.hypixel.hytale.server.core.asset.type.soundevent.config.SoundEvent.getAssetMap();
    if (m != null && m.getIndex(v) == Integer.MIN_VALUE) return "The game has no sound event '" + v + "' - find ids with /soundtest list, or leave it empty for no sound.";
  } catch (Throwable t) { }
  return null;
}""")
M(qsnd, r"""
public static String check(String key, String value) {
  return err(value);
}""")
M(qsnd, r"""
public static String pick(boolean master, boolean on, String id) {
  if (!master || !on || id == null) return null;
  String v = id.trim();
  return v.length() == 0 ? null : v;
}""")
M(qsnd, r"""
public static com.hypixel.hytale.server.core.universe.PlayerRef ref(java.util.UUID u) {
  if (u == null) return null;
  try {
    com.hypixel.hytale.server.core.universe.Universe uni = com.hypixel.hytale.server.core.universe.Universe.get();
    return uni == null ? null : uni.getPlayer(u);
  } catch (Throwable t) { return null; }
}""")
M(qsnd, r"""
public static boolean gate(String key, long now) {
  Object o = LAST.get(key);
  if (o instanceof Long) { long d = now - ((Long) o).longValue(); if (d >= 0L && d < GAP_MS) return false; }
  if (LAST.size() > 4096) LAST.clear();
  LAST.put(key, Long.valueOf(now));
  return true;
}""")
M(qsnd, r"""
public static boolean playTo(com.hypixel.hytale.server.core.universe.PlayerRef pr, String id, String tag) {
  if (pr == null || id == null) return false;
  try {
    if (!pr.isValid()) return false;
    int i = idx(id);
    if (i == Integer.MIN_VALUE || i == 0) {
      if (WARNED.putIfAbsent(id, Boolean.TRUE) == null) @PKG@.QLog.warn("sound event '" + id + "' is not in the game assets - it is not played (Server Setup -> Quests -> Sounds)");
      return false;
    }
    if (!gate(String.valueOf(pr.getUuid()) + "|" + tag, System.currentTimeMillis())) return false;
    com.hypixel.hytale.server.core.universe.world.SoundUtil.playSoundEvent2dToPlayer(pr, i, com.hypixel.hytale.protocol.SoundCategory.UI);
    PLAYED.incrementAndGet();
    return true;
  } catch (Throwable t) { @PKG@.QLog.warnOnce("sound", "could not play a sound (logged once): " + t); return false; }
}""")
M(qsnd, r"""
public static boolean play(java.util.UUID u, String id, String tag) {
  if (id == null || u == null) return false;
  return playTo(ref(u), id, tag);
}""")

