M(defs, r"""
public static int typeOf(String s) {
  if (s == null) return 0;
  String t = s.trim().toLowerCase(java.util.Locale.ROOT);
  for (int i = 0; i < TYPES.length; i++) if (TYPES[i].equals(t)) return 1 << i;
  return 0;
}""")
M(defs, r"""
public static String typeName(int bit) {
  for (int i = 0; i < TYPES.length; i++) if ((1 << i) == bit) return TYPES[i];
  return "?";
}""")
# a glob with * (any run of characters), case-sensitive like the game's ids
M(defs, r"""
public static boolean glob(String pat, String s) {
  if (pat == null || s == null) return false;
  if (pat.indexOf('*') < 0) return pat.equals(s);
  String[] parts = pat.split("\\*", -1);
  int pos = 0;
  for (int i = 0; i < parts.length; i++) {
    String p = parts[i];
    if (i == 0) { if (!s.startsWith(p)) return false; pos = p.length(); continue; }
    if (i == parts.length - 1) return s.length() - pos >= p.length() && s.endsWith(p);
    if (p.length() == 0) continue;
    int k = s.indexOf(p, pos);
    if (k < 0) return false;
    pos = k + p.length();
  }
  return true;
}""")
# "any" / "" = everything; else alternatives a|b|c, each a glob
M(defs, r"""
public static boolean matches(String pat, String s) {
  if (pat == null || pat.length() == 0 || pat.equals("any")) return true;
  if (s == null) return false;
  if (pat.indexOf('|') < 0) return glob(pat, s);
  String[] a = pat.split("\\|");
  for (int i = 0; i < a.length; i++) if (glob(a[i].trim(), s)) return true;
  return false;
}""")
M(defs, r"""
public static boolean idOk(String s) {
  if (s == null || s.length() == 0 || s.length() > 40) return false;
  char c0 = s.charAt(0);
  if (c0 < 'a' || c0 > 'z') return false;
  for (int i = 1; i < s.length(); i++) {
    char c = s.charAt(i);
    if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_')) return false;
  }
  return true;
}""")
# one reward list "coins:25,xp:Foraging:50,item:Rock_Stone:3,flag:met_marlow" -> null = fine, else why not
M(defs, r"""
public static String rewardProblem(String r) {
  if (r == null || r.trim().length() == 0) return null;
  String[] a = r.split(",");
  for (int i = 0; i < a.length; i++) {
    String x = a[i].trim();
    if (x.length() == 0) continue;
    String[] p = x.split(":");
    if (p[0].equals("coins") && p.length == 2 && @PKG@.QLog.num(p[1], -1L) > 0L) continue;
    if (p[0].equals("xp") && p.length == 3 && @PKG@.QLog.num(p[2], -1L) > 0L) {
      boolean ok = false;
      for (int k = 0; k < SKILLS.length; k++) if (SKILLS[k].equals(p[1])) ok = true;
      if (!ok) return "'" + x + "': " + p[1] + " XP cannot be granted by another mod (SkyySkills grants " + java.util.Arrays.toString(SKILLS) + ")";
      continue;
    }
    if (p[0].equals("item") && p.length == 3 && p[1].length() > 0 && @PKG@.QLog.num(p[2], -1L) > 0L && @PKG@.QLog.num(p[2], -1L) <= 1000L) continue;
    if (p[0].equals("flag") && p.length == 2 && idOk(p[1])) continue;
    if (p[0].equals("pole") && p.length == 2 && p[1].equals("starter")) continue;    // 0.3: SkyyFishing's starter rod (fishing:fn:starter)
    if (p[0].equals("gear") && p.length == 2) {                       // 0.2: gear:weapon / gear:armor (an unidentified bag, SkyyGear)
      boolean ok = false;
      for (int k = 0; k < GEAR_KINDS.length; k++) if (GEAR_KINDS[k].equals(p[1])) ok = true;
      if (ok) continue;
    }
    return "'" + x + "' is not coins:N, xp:<Skill>:N, item:<id>:N (1-1000), gear:weapon, gear:armor, gear:head / chest / hands / legs, gear:second, pole:starter or flag:<name>";
  }
  return null;
}""")
M(defs, r"""
public static @PKG@.QPart part(java.util.Properties p, String pre, String where, java.util.List err) {
  @PKG@.QPart q = new @PKG@.QPart();
  q.tname = p.getProperty(pre + "type", "").trim();
  q.type = typeOf(q.tname);
  if (q.type == 0) { err.add(where + ": " + pre + "type '" + q.tname + "' is not one of " + java.util.Arrays.toString(TYPES)); return null; }
  q.match = p.getProperty(pre + "match", "").trim();
  q.count = @PKG@.QLog.num(p.getProperty(pre + "count"), 1L);
  if (q.count < 1L || q.count > 1000000L) { err.add(where + ": " + pre + "count must be 1-1000000 (1 used)"); q.count = 1L; }
  q.op = p.getProperty(pre + "op", "").trim();
  q.value = p.getProperty(pre + "value", "").trim();
  q.caller = p.getProperty(pre + "caller", "").trim();
  q.radius = @PKG@.QLog.dec(p.getProperty(pre + "radius"), 8.0);
  if (q.radius < 1.0) q.radius = 1.0;
  if (q.radius > 256.0) q.radius = 256.0;
  q.ripe = @PKG@.QLog.bool(p.getProperty(pre + "ripe"), false);
  q.block = @PKG@.QLog.bool(p.getProperty(pre + "block"), false);
  // 0.2 LEAD (Skyy's log: "See a collection rank up" done with no rank-up): a tier part on ANY collection needs a NEW rank-up by default
  q.fresh = @PKG@.QLog.bool(p.getProperty(pre + "new"), q.type == @TTIER@ && (q.match.length() == 0 || q.match.equals("any")));
  q.party = @PKG@.QLog.bool(p.getProperty(pre + "party"), false);
  q.alt = p.getProperty(pre + "alt", "").trim();                                    // 0.3.3: one part of the group is enough
  q.label = @PKG@.QLog.clean(p.getProperty(pre + "label", ""));                     // 0.3.3: the part's name on a progress card
  q.meta = p.getProperty(pre + "meta", "").trim();                                  // 0.4.4: have parts - only stacks carrying this metadata key
  if (q.meta.length() > 0 && q.type != @THAVE@) { err.add(where + ": " + pre + "meta works on have parts only (ignored)"); q.meta = ""; }
  if (q.match.length() == 0 && q.type != @TFELLE@ && q.type != @TKILL@ && q.type != @TTIER@) { err.add(where + ": " + pre + "match is empty"); return null; }
  if (q.fresh && !(q.type == @TTIER@ || q.type == @TLEVEL@ || q.type == @TBRIDG@)) { err.add(where + ": " + pre + "new=true works on tier / level / bridge parts only (ignored)"); q.fresh = false; }
  if (q.party && q.type != @TKILL@) { err.add(where + ": " + pre + "party=true works on kill parts only (ignored)"); q.party = false; }
  if (q.type == @TBRIDG@ && !(q.op.equals("exists") || q.op.equals("notempty") || q.op.equals(">=") || q.op.equals("contains"))) {
    err.add(where + ": " + pre + "op '" + q.op + "' (bridge: exists, notempty, >= or contains)"); return null;
  }
  boolean needV = q.type == @TTIER@ || q.type == @TLEVEL@ || (q.type == @TBRIDG@ && (q.op.equals(">=") || q.op.equals("contains")));
  if (needV && q.value.length() == 0) { err.add(where + ": " + pre + "value is empty"); return null; }
  if (q.fresh && q.type == @TBRIDG@ && !q.op.equals(">=")) { err.add(where + ": " + pre + "new=true on a bridge part needs op >= (ignored)"); q.fresh = false; }
  boolean numV = q.type == @TTIER@ || q.type == @TLEVEL@ || (q.type == @TBRIDG@ && q.op.equals(">="));
  if (numV && @PKG@.QLog.num(q.value, -1L) < 0L) { err.add(where + ": " + pre + "value '" + q.value + "' is not a whole number"); return null; }
  return q;
}""")
# 0.4.4 (spec 12): the tutorial's first_shard waited on island:shard (no mod sends it). While its fields still hold the old SHIPPED values
# they load as "Open a shard door" = event shard:door:* (SkyyShards 0.4.8), requires shard:fn:door - in memory only (the 0.4.1 way: no file
# on disk changes; an owner's own match / requires / name / hint is kept). The progress key (part 0) and the reward are unchanged.
M(defs, r"""
public static boolean shard044(java.util.Properties p) {
  for (int n = 1; n <= 200; n++) {
    String pre = "task." + n + ".";
    String id = p.getProperty(pre + "id");
    if (id == null || !id.trim().equals("first_shard")) continue;
    if (p.getProperty(pre + "p1.type") != null || p.getProperty(pre + "p2.type") != null) return false;
    if (!"event".equals(String.valueOf(p.getProperty(pre + "type")).trim()) || !"island:shard".equals(String.valueOf(p.getProperty(pre + "match")).trim())) return false;
    p.setProperty(pre + "match", "shard:door:*");
    if ("islands".equals(String.valueOf(p.getProperty(pre + "caller")).trim())) p.remove(pre + "caller");
    if ("@FSREQ@".equals(String.valueOf(p.getProperty(pre + "requires")).trim())) p.setProperty(pre + "requires", "shard:fn:door");
    if ("@FSNAME@".equals(String.valueOf(p.getProperty(pre + "name")).trim())) p.setProperty(pre + "name", "@FSNEWN@");
    if ("@FSHINT@".equals(String.valueOf(p.getProperty(pre + "hint")).trim())) p.setProperty(pre + "hint", "@FSNEWH@");
    return true;
  }
  return false;
}""".replace("@FSREQ@", FS_OLD[5]).replace("@FSNAME@", FS_OLD[0]).replace("@FSHINT@", FS_OLD[1]).replace("@FSNEWN@", FS_NEW_NAME).replace("@FSNEWH@", FS_NEW_HINT))
M(defs, r"""
public static @PKG@.QLine parse(java.util.Properties p, String file, java.util.List err) {
  @PKG@.QLine l = new @PKG@.QLine();
  l.file = file;
  l.id = p.getProperty("line", "").trim();
  if (!idOk(l.id)) { err.add(file + ": line=" + l.id + " must be [a-z][a-z0-9_]* (1-40) - file skipped"); return null; }
  l.name = @PKG@.QLog.clean(p.getProperty("name", l.id));
  String mode = p.getProperty("mode", "open").trim();
  if (!mode.equals("open") && !mode.equals("chain") && !mode.equals("daily")) err.add(file + ": mode=" + mode + " (open, chain or daily) - open used");
  l.chain = mode.equals("chain");
  l.daily = mode.equals("daily");                                                   // 0.3: the board's daily jobs
  l.giver = p.getProperty("giver", "").trim();                                      // 0.3: the quest NPC that offers this line
  l.auto = @PKG@.QLog.bool(p.getProperty("auto"), false);
  l.hide = p.getProperty("hide.setting", "").trim();
  l.order = (int) @PKG@.QLog.num(p.getProperty("order"), 100L);                  // 0.2: the widget's line order (tutorial 0)
  l.area = p.getProperty("area", "").trim();
  l.shortAfter = p.getProperty("short.after", "").trim();
  if ("tutorial".equals(l.id)) shard044(p);                                         // 0.4.4: the old shipped first_shard -> "Open a shard door"
  java.util.ArrayList ts = new java.util.ArrayList();
  java.util.HashSet ids = new java.util.HashSet();
  for (int n = 1; n <= 200; n++) {
    String pre = "task." + n + ".";
    String id = p.getProperty(pre + "id");
    if (id == null) continue;
    String where = file + " task " + n;
    @PKG@.QTask t = new @PKG@.QTask();
    t.id = id.trim();
    if (!idOk(t.id) || !ids.add(t.id)) { err.add(where + ": id '" + t.id + "' must be [a-z][a-z0-9_]* and unique - task skipped"); continue; }
    t.name = @PKG@.QLog.clean(p.getProperty(pre + "name", t.id));
    t.where = p.getProperty(pre + "where", "").trim();
    t.hint = @PKG@.QLog.clean(p.getProperty(pre + "hint", ""));
    if ("tutorial".equals(l.id) && "first_accessory".equals(t.id) && ("Craft one at a bench, then put it in your Accessory Bag".equals(t.hint) || "Craft one in your Accessory Bag's Craft tab".equals(t.hint)))
      t.hint = "Craft one in your Void Charms' Craft tab";     // 0.4.2: Void Charms (was the Accessory Bag); 0.4.0: the old shipped texts only (an owner's own hint is kept)
    t.reward = p.getProperty(pre + "reward", "").trim();
    if ("tutorial".equals(l.id) && "defeat_mobs".equals(t.id) && "gear:weapon,gear:armor".equals(t.reward))
      t.reward = "gear:head,gear:chest,gear:hands,gear:legs,gear:second";     // 0.4.1: the old shipped reward only (an owner's own reward is kept) - a full armor set + the second weapon
    t.requires = p.getProperty(pre + "requires", "").trim();
    t.any = @PKG@.QLog.bool(p.getProperty(pre + "any"), false);
    t.optional = @PKG@.QLog.bool(p.getProperty(pre + "optional"), false);          // 0.2
    t.island = @PKG@.QLog.bool(p.getProperty(pre + "island"), false);
    t.tut = @PKG@.QLog.bool(p.getProperty(pre + "tut"), false);
    t.tier = (int) @PKG@.QLog.num(p.getProperty(pre + "tier"), 0L);                  // 0.3
    if (l.daily && (t.tier < 1 || t.tier > 3)) { err.add(where + " (" + t.id + "): tier must be 1, 2 or 3 on a daily line (1 used)"); t.tier = 1; }
    String rp = rewardProblem(t.reward);
    if (rp != null) { err.add(where + " (" + t.id + "): reward " + rp + " - reward ignored"); t.reward = ""; }
    String wv = p.getProperty(pre + "was", "").trim();                             // 0.3.3: was=<old task>:<first part>
    if (wv.length() > 0) {
      int wc = wv.indexOf(':');
      String wi = wc > 0 ? wv.substring(0, wc).trim() : "";
      long wa = wc > 0 ? @PKG@.QLog.num(wv.substring(wc + 1).trim(), -1L) : -1L;
      if (!idOk(wi) || wi.equals(t.id) || wa < 1L || wa > 7L) err.add(where + " (" + t.id + "): was=" + wv + " must be <old task id>:<its first part number, 1-7> - ignored");
      else { t.was = wi; t.wasAt = (int) wa; }
    }
    t.wasReward = p.getProperty(pre + "was.reward", "").trim();
    String wrp = rewardProblem(t.wasReward);
    if (wrp != null) { err.add(where + " (" + t.id + "): was.reward " + wrp + " - ignored"); t.wasReward = ""; }
    java.util.ArrayList ps = new java.util.ArrayList();
    if (p.getProperty(pre + "type") != null) {
      @PKG@.QPart q = part(p, pre, where, err);
      if (q != null) ps.add(q);
    } else {
      for (int k = 1; k <= 8; k++) {
        if (p.getProperty(pre + "p" + k + ".type") == null) continue;
        @PKG@.QPart q = part(p, pre + "p" + k + ".", where, err);
        if (q != null) ps.add(q);
      }
    }
    if (ps.isEmpty()) { err.add(where + " (" + t.id + "): no valid objective - task skipped"); continue; }
    t.parts = new @PKG@.QPart[ps.size()];
    for (int k = 0; k < t.parts.length; k++) t.parts[k] = (@PKG@.QPart) ps.get(k);
    if (t.was.length() > 0 && t.wasAt >= t.parts.length) { err.add(where + " (" + t.id + "): was=" + t.was + ":" + t.wasAt + " points past its last part - ignored"); t.was = ""; t.wasAt = 0; }
    t.n = ts.size();
    ts.add(t);
  }
  l.tasks = new @PKG@.QTask[ts.size()];
  for (int i = 0; i < l.tasks.length; i++) l.tasks[i] = (@PKG@.QTask) ts.get(i);
  if (l.tasks.length == 0) err.add(file + ": no tasks");
  return l;
}""")
M(defs, r"""
public static @PKG@.QPlace placeOf(String id, String v) {
  if (id == null || v == null) return null;
  String[] a = v.split("\\|");
  if (a.length < 4) return null;
  try {
    String w = a[0].trim();
    if (w.length() == 0) return null;
    double x = Double.parseDouble(a[1].trim()); double y = Double.parseDouble(a[2].trim()); double z = Double.parseDouble(a[3].trim());
    String lab = a.length > 4 ? @PKG@.QLog.clean(a[4]) : id;
    if (lab.length() == 0) lab = id;
    return new @PKG@.QPlace(id, w, x, y, z, lab);
  } catch (Throwable t) { return null; }
}""")
