# 0.3.3: a task with was=<old>:<at> (the old task is no longer in its line): the old task's part counts / done parts -> parts at.. (the
# higher count wins); the old task done (or paid) = those parts met; this task done while the old one was never paid = REOPENED (its own
# parts kept as met; issued stays, so its own reward is never paid twice - completeOneL pays the old task's reward then). Never removes a
# key except that one done line (the old keys stay for a rollback); idempotent; true = changed (the state is written at the next flush).
M(st_, r"""
public static boolean fold(@PKG@.QState s) {
  if (s == null || s.frozen) return false;
  boolean ch = false;
  @PKG@.QLine[] ls = @PKG@.QDefs.LINES;
  for (int li = 0; li < ls.length; li++) {
    @PKG@.QLine l = ls[li];
    for (int i = 0; i < l.tasks.length; i++) {
      @PKG@.QTask t = l.tasks[i];
      if (t.was == null || t.was.length() == 0 || t.wasAt <= 0 || t.wasAt >= t.parts.length) continue;
      boolean still = false;
      for (int j = 0; j < l.tasks.length; j++) if (l.tasks[j].id.equals(t.was)) still = true;
      if (still) continue;
      String fm = "folded." + l.id + "." + t.id;   // FIX (critic): ONCE per profile + task (an admin undo stays undone; kept as a plain extra key)
      if (s.extra.containsKey(fm)) continue;
      s.extra.put(fm, "1");
      ch = true;
      String k = l.id + "." + t.id;
      String o = l.id + "." + t.was;
      boolean odn = s.done.containsKey(o) || s.issued.contains(o);
      for (int j = 0; t.wasAt + j < t.parts.length; j++) {
        String a = o + "." + j;
        String b = k + "." + (t.wasAt + j);
        Object pa = s.prog.get(a);
        Object pb = s.prog.get(b);
        long va = pa instanceof Long ? ((Long) pa).longValue() : 0L;
        long vb = pb instanceof Long ? ((Long) pb).longValue() : 0L;
        if (va > vb) { s.prog.put(b, Long.valueOf(va)); vb = va; ch = true; }
        if ((odn || s.pdone.contains(a)) && !s.pdone.contains(b)) {
          s.pdone.add(b);
          long need = t.parts[t.wasAt + j].count;
          if (vb < need) s.prog.put(b, Long.valueOf(need));
          ch = true;
        }
      }
      if (s.done.containsKey(k) && !odn) {
        s.done.remove(k);
        boolean met = false;
        for (int j = 0; j < t.wasAt; j++) if (s.pdone.contains(k + "." + j)) met = true;
        if (!met) for (int j = 0; j < t.wasAt; j++) { s.pdone.add(k + "." + j); s.prog.put(k + "." + j, Long.valueOf(t.parts[j].count)); }
        ch = true;
      }
    }
  }
  if (ch) s.ver = s.ver + 1L;
  return ch;
}""")
