# 0.3.3 (Skyy: "it says mine 64 stone and 18/50"): a progress card says its own count - "Mine 64 stone 4 / 64", a labelled part of a
# merged task "Gather logs, stone and copper: stone 4 / 10" (the text of feed:fn:push; SkyyHud unchanged)
M(eng, r"""
public static String cardText(Object[] c) {
  @PKG@.QTask t = (@PKG@.QTask) c[1];
  if (c.length < 6) return t.name;
  int mp = ((Integer) c[2]).intValue();
  long n = ((Long) c[3]).longValue();
  long need = ((Long) c[4]).longValue();
  if (n > need) n = need;
  String lab = mp >= 0 && mp < t.parts.length ? t.parts[mp].label : "";
  return t.name + (lab != null && lab.length() > 0 ? ": " + lab : "") + " " + n + " / " + need;
}""")
# the card's icon = the counted block / item id when it looks like one (SkyyHud checks it is a real item; one icon = SkyyHud merges the
# cards of that task into ONE card that updates its text instead of a new card per block); kills / events: none
# FIX (critic): only a REAL item id is an icon (SkyyHud drops any other, and then keys its merge on the text, which now changes with the
# count) - a kill role / event key / block that is not an item gets no icon and is throttled in notifyProgress (CARD_GAP_MS)
F(eng, "public static final java.util.concurrent.ConcurrentHashMap CARD_LAST = new java.util.concurrent.ConcurrentHashMap();")   # "uuid|line.task" -> ms
F(eng, "public static final long CARD_GAP_MS = 5000L;")              # SkyyHud shows a card 4 s + a 1 s fade (feed.showSecs default)
F(eng, "public static volatile java.util.Set CARD_ITEMS = null;")     # harness only: the item ids (null in the game = the Item asset map)
M(eng, r"""
public static boolean cardItem(String k) {
  java.util.Set ts = CARD_ITEMS;
  if (ts != null) return ts.contains(k);
  try {
    com.hypixel.hytale.assetstore.map.DefaultAssetMap m = @ITM@.getAssetMap();
    if (m == null || m.getAssetCount() <= 0) return true;
    return m.getAsset(k) != null;
  } catch (Throwable t) { return true; }
}""")
M(eng, r"""
public static String cardIcon(Object[] c) {
  if (c.length < 6 || !(c[5] instanceof String)) return null;
  String k = (String) c[5];
  if (k.length() == 0 || k.length() > 64 || k.equals("any")) return null;
  for (int i = 0; i < k.length(); i++) {
    char ch = k.charAt(i);
    if (!((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') || ch == '_')) return null;
  }
  return cardItem(k) ? k : null;
}""")
# progress: ONE feed card per counted event - the task of the widget's line if it moved, else the first one that moved
M(eng, r"""
public static void notifyProgress(@PKG@.QP p, @PKG@.QState s, java.util.List progd, long amt, long now) {
  if (progd.isEmpty()) return;
  Object[] c = (Object[]) progd.get(0);
  @PKG@.QLine tl = null;
  try { if (s != null) tl = s.tracked(p, now); } catch (Throwable x) { tl = null; }     // FIX (critic): under the state's lock
  if (tl != null) {
    for (int i = 0; i < progd.size(); i++) {
      Object[] e = (Object[]) progd.get(i);
      if (e[0] == tl) { c = e; break; }
    }
  }
  String ic = cardIcon(c);
  if (ic == null) {          // FIX (critic): no item icon = SkyyHud cannot merge these cards - at most one per task while its card is on screen
    String ck = p.u.toString() + "|" + ((@PKG@.QLine) c[0]).id + "." + ((@PKG@.QTask) c[1]).id;
    Object lo = CARD_LAST.get(ck);
    if (lo instanceof Long) {
      long d = now - ((Long) lo).longValue();
      if (d >= 0L && d < CARD_GAP_MS) return;
    }
    if (CARD_LAST.size() > 4096) CARD_LAST.clear();
    CARD_LAST.put(ck, Long.valueOf(now));
  }
  feed(p, cardText(c), ic, Long.valueOf(amt));
}""")
