# the position hop result (the player's world thread, QHop): reach objectives + the arrow
M(eng, r"""
public static void position(@PKG@.QP p, String world, double x, double y, double z) {
  p.world = world; p.x = x; p.y = y; p.z = z;
  @PKG@.QState s = stateOf(p);
  if (s == null) return;
  if (@PKG@.QDefs.AREAS.length > 0) enterArea(p, areaAt(world, x, z, true), world);      // 0.2: region + world areas
  long now = System.currentTimeMillis();
  Object w = WANT.get(p.u);
  if (w instanceof Integer && (((Integer) w).intValue() & @TREACH@) != 0 && s.pk.equals(@PKG@.QLog.pkey(p.u)) && !@PKG@.QLog.bridge().containsKey("profile:busy:" + p.u.toString())) {
    java.util.ArrayList out = new java.util.ArrayList();
    if (s.reach(world, x, y, z, now, out)) after(p, s, out, null, 0L, now);
  }
  String dp = p.dirPlace;
  String txt = "";
  int[] dir = new int[] { -1 };
  @PKG@.QPlace q = @PKG@.QDefs.place(dp);
  if (q != null && worldMatch(q.world, world)) txt = dirText(q, x, z, dir);
  String df = dp == null ? "" : dp;
  if (!txt.equals(p.dirText) || !df.equals(p.dirFor) || dir[0] != p.dir) {
    p.dirText = txt; p.dir = dir[0]; p.dirFor = df;
    bump(p.u);
  }
}""")
# 0.4.4 have parts: the items held (storage + hotbar + backpack) that match the part (an id / glob / a|b; meta = only stacks whose metadata
# document has that key, e.g. CapturedEntity = a full Capture Crate). The player's WORLD THREAD only (QHop).
M(eng, r"""
public static long haveCount(@IC@[] cs, String pat, String meta) {
  long n = 0L;
  boolean mt = meta != null && meta.length() > 0;
  for (int c = 0; c < cs.length; c++) {
    @IC@ ic = cs[c];
    if (ic == null) continue;
    short cap = ic.getCapacity();
    for (short i = 0; i < cap; i++) {
      @IS@ it = ic.getItemStack(i);
      if (it == null || it.isEmpty() || !@PKG@.QDefs.matches(pat, it.getItemId())) continue;
      if (mt) {
        org.bson.BsonDocument md = it.getMetadata();
        if (md == null || !md.containsKey(meta)) continue;
      }
      n += (long) it.getQuantity();
    }
  }
  return n;
}""")
