F(eng, "public static volatile long RW_MS = 3000L;")
M(eng, r"""
public static boolean reachWorld(String world, long now) {
  if (world == null) return false;
  Object c = RWC.get(world);
  if (c instanceof long[] && ((long[]) c)[0] > now) return ((long[]) c)[1] != 0L;
  boolean r = false;
  @PKG@.QLine[] ls = @PKG@.QDefs.LINES;
  for (int li = 0; li < ls.length && !r; li++) {
    @PKG@.QTask[] ts = ls[li].tasks;
    for (int i = 0; i < ts.length && !r; i++) {
      @PKG@.QPart[] ps = ts[i].parts;
      for (int pi = 0; pi < ps.length && !r; pi++) {
        if (ps[pi].type != @TREACH@) continue;
        @PKG@.QPlace q = @PKG@.QDefs.place(ps[pi].match);
        if (q != null && worldMatch(q.world, world)) r = true;
      }
    }
  }
  if (RWC.size() > 256) RWC.clear();
  RWC.put(world, new long[] { now + RW_MS, r ? 1L : 0L });
  return r;
}""")
