# 0.4.0 (World > Quests): the waiting claim lines of ONE task (its key k, or its folded old task k2) - "Ready to claim" + the task's Claim.
# A claim line = "<type>|<payload>|<pkey>:<key>:<seq>"; the payer takes a claim off the list before it pays (so a paying one is not counted)
M(st_, r"""
public synchronized int waitingOf(String k, String k2) {
  if (this.frozen || k == null) return 0;
  int n = 0;
  for (int i = 0; i < this.claims.size(); i++) {
    String c = (String) this.claims.get(i);
    int b = c.lastIndexOf('|');
    String g = b < 0 ? c : c.substring(b + 1);
    if (g.indexOf(":" + k + ":") >= 0 || (k2 != null && g.indexOf(":" + k2 + ":") >= 0)) n++;
  }
  return n;
}""")
# the task's Claim: ONLY its own refused marks go and the payer runs now (the payer and the ledger are unchanged - each claim pays once)
M(st_, r"""
public synchronized int retryTask(String k, String k2) {
  if (this.frozen || k == null) return 0;
  int n = 0;
  for (int i = 0; i < this.claims.size(); i++) {
    String c = (String) this.claims.get(i);
    int b = c.lastIndexOf('|');
    String g = b < 0 ? c : c.substring(b + 1);
    if (g.indexOf(":" + k + ":") >= 0 || (k2 != null && g.indexOf(":" + k2 + ":") >= 0)) { this.refused.remove(c); n++; }
  }
  if (n > 0) this.bounceAt = 0L;
  return n;
}""")
