M(eng, r"""
public static Object[] findTask(String key) {
  if (key == null) return null;
  String k = key.trim();
  @PKG@.QLine[] ls = @PKG@.QDefs.LINES;
  int d = k.indexOf('.');
  for (int li = 0; li < ls.length; li++) {
    if (d > 0 && !ls[li].id.equals(k.substring(0, d))) continue;
    String tid = d > 0 ? k.substring(d + 1) : k;
    for (int i = 0; i < ls[li].tasks.length; i++) if (ls[li].tasks[i].id.equals(tid)) return new Object[] { ls[li], ls[li].tasks[i] };
  }
  return null;
}""")
M(eng, r"""
public static String action(java.util.UUID u, String a, String lineId) {
  @PKG@.QP p = player(u);
  @PKG@.QState s = stateOf(p);
  if (s == null) return "-Your quests are still loading - try again in a moment.";
  if (a.equals("track")) {
    @PKG@.QLine l = @PKG@.QDefs.line(lineId);
    if (l == null) return "-No quest line '" + lineId + "'.";
    if (!lineActive(s, l)) return "-" + l.name + " is not active for you yet.";
    s.setTrack(l.id);
    bump(u);
    return "+Tracking " + l.name + " in your quest widget.";
  }
  if (a.equals("untrack")) {                                     // 0.4.0: World > Quests' Track this line toggle (off = the empty track=)
    if (lineId == null || !lineId.equals(s.track)) return "=That line is not pinned to your quest widget.";
    s.setTrack("");
    bump(u);
    return "+Unpinned - your quest widget follows your next open line again.";
  }
  if (a.equals("claim")) {
    if (!s.hasClaims()) return "=No rewards are waiting.";
    s.retryNow();
    wake();
    return "+Paying your waiting rewards now (make room in your bags for items).";
  }
  if (a.equals("skip")) {                                        // 0.2: Skip / Unskip (Skyy: "bypassing tutorial quests needs to be simple and easy")
    Object[] f = findTask(lineId);
    if (f == null) return "-No task '" + lineId + "' (see /quests).";
    @PKG@.QLine l = (@PKG@.QLine) f[0];
    @PKG@.QTask t = (@PKG@.QTask) f[1];
    long now = System.currentTimeMillis();
    int r = s.skipToggle(tk(l, t), now);
    if (r == 0) return "=" + t.name + " is already done.";
    if (r == 1) {                                                // 0.3.3: a skip makes the next chain step active - already met = done now
      java.util.ArrayList co = new java.util.ArrayList();
      s.cascade(l, now, co);
      if (!co.isEmpty()) after(p, s, co, null, 0L, now);
    }
    bump(u);
    wake();
    return r == 1 ? "+Skipped: " + t.name + " - it leaves your widget (it still counts and pays if you do it later)." : "+" + t.name + " is back in your widget.";
  }
  if (a.equals("hide")) { setHide(u, true); return "+Tutorial tasks hidden from your widget - they still count and still pay."; }
  if (a.equals("show")) { setHide(u, false); return "+Tutorial tasks are back in your widget."; }
  return "-Unknown action.";
}""")


