def q_preview(lock=False, search=False, empty=False):
    """0.4.0 build-time check: one whole view as the build draws it - the hub_page shell + row 1 + row 2 (every World contract tab, Quests
    selected) + the sub row (+ the search box) + the content with one line row / task row (or the empty states) + the panel + the footer:
    valid markup, proven styles, the Sky Window paths, SUI.assert_menu_page (1600 x 980, rows 1 + 2, one sub row, no back / < Menu, no pager,
    the content fits)."""
    pv = SUI.hub_page_preview(LSH, tabs=[(r[0], SUI.hub_tab_label(Q_HUB, r[0])) for r in SUI.hub_page_tabs(Q_HUB)], my_tab=Q_TAB)
    pv.extend(SUI.sub_tabs_preview(LSH.prefix, Q_SUBS, 0))
    if search:
        pv.extend([(LSH.sub, Q_SFLEX), (LSH.sub, Q_SFIELD), (LSH.sub, Q_SBTN)])
    pv.extend(QL)
    r = lambda mk: SUI.render(mk) if isinstance(mk, str) else mk
    if empty:
        pv.extend([("SkyyQlLL", Q_LEMPTY), ("SkyyQlList", Q_TEMPTY), ("SkyyQlDet", Q_DEMPTY)])
    else:
        if lock:
            pv.extend([("SkyyQlLL", Q_LROW_LOCK), ("SkyyQlL0Sel", Q_LTEXT), ("SkyyQlLT0", Q_LNAME), ("SkyyQlLT0", Q_LSUB)])
        else:
            pv.extend([("SkyyQlLL", Q_LROW.b), ("SkyyQlL0Sel", Q_LTEXT), ("SkyyQlLT0", Q_LNAME), ("SkyyQlLT0", Q_LSUB), ("SkyyQlLT0", Q_LBAR),
                       ("SkyyQlL0Sel", Q_LCNT)])
        pv.extend([("SkyyQlList", Q_TROW.a), ("SkyyQlR0Sel", Q_TNAME), ("SkyyQlR0Sel", Q_TPROG), ("SkyyQlR0Sel", Q_TBARW), ("SkyyQlBW0", Q_TBAR),
                   ("SkyyQlList", Q_FOLD), ("SkyyQlFoldSel", Q_FOLDT)])
        pv.extend(QD)
        pv.extend([("SkyyQlDBtns", Q_DSKIP.b), ("SkyyQlDBtns", Q_DCLAIM)])
    pv.extend([(LSH.foot, Q_FINFO), (LSH.foot, Q_FGAP), (LSH.foot, Q_FTRACK), (LSH.foot, Q_FGAP), (LSH.foot, Q_FCLAIM)])
    SUI.check_page(pv, "SkyyQl")
    SUI.assert_proven(pv, allow=("base", "base4"), what="SkyyQuests 0.4.0 World > Quests")
    els = SUI.check_sky_paths(pv, tab_icons=True)
    assert {"Header", "HeaderOrnament", SUI.HUB_FRAME[Q_HUB], "Close"} <= set(els), "0.4.0: the Sky Window shell: %s" % els
    sets = [("#SkyyQlN0.Text", "T1 Chop 10 logs"), ("#SkyyQlTrack.Text", "Tracked on HUD"), ("#SkyyQlClaim.Text", "Claim all (3)"),
("#SkyyQlFoldT.Text", "+ 11 done"), ("#SkyyQlHead.Text", "Getting Started   11 / 23 done")]
    info = SUI.assert_menu_page(pv, LSH, what="SkyyQuests 0.4.0 World > Quests", sets=sets)
    assert info["rows"] == 2 and info["subs"] == 1, info
    return pv


