def qrep(src):
    """the page's own build-time numbers into its Java (before jv: its tokens are not T keys)"""
    return (src.replace("@QPRE@", LSH.prefix).replace("@QSUB0@", Q_SUBS[0]).replace("@QSUB1@", Q_SUBS[1]).replace("@QSUBW@", str(SUI.SUB_TAB_W))
    .replace("@QSMIN@", str(Q_SEARCH_MIN)).replace("@QAVAIL@", str(Q_AVAIL)).replace("@QRGAP@", str(Q_RGAP)).replace("@QLBW@", str(Q_LBW))
    .replace("@QBW@", str(Q_BW)).replace("@QDIW@", str(Q_DIW)).replace("@QHINT@", Q_HINT)
    .replace("@CDIS@", Q_JC["disabled"]).replace("@CRN@", Q_JC["rowName"]).replace("@CSUC@", Q_JC["success"]).replace("@CSUB@", Q_JC["rowSub"])
    .replace("@CGOLD@", Q_JC["gold"]))


