M(lpage, r"""
public void handleDataEvent(@REF@ ref, @ST@ st, String data) {
  String a = @PKG@.QWelcomePage.jsonStr(data, "a");
  java.util.UUID u = this.playerRef.getUuid();
  try {
    String hr = @PKG@.HubBar.route(this.playerRef, data, "world", "quests");     // row 1 (hub:h:<id>; World = self), row 2 (hub:<tab>), the X
    if (hr != null) {
      if (hr.equals("close")) { close(); return; }
      if (!hr.equals("self")) {
        if (!hr.equals("bridge") && !hr.equals("command") && !hr.equals("back")) { this.info = "-That tab could not open right now - try again."; rebuild(); }
        return;
      }
      this.info = "";
      this.sub = 0;
    } else if (a.equals("close")) { close(); return; }
    else if (a.equals("sub:open")) { this.sub = 0; this.info = ""; }
    else if (a.equals("sub:done")) { this.sub = 1; this.info = ""; }
    else if (a.startsWith("line:")) { this.line = a.substring(5); this.task = null; this.find = ""; this.info = ""; }
    else if (a.startsWith("task:")) this.task = a.substring(5);
    else if (a.equals("find")) { String f = @PKG@.QWelcomePage.jsonStr(data, String.valueOf((char) 64) + "Find"); this.find = f.length() > 40 ? f.substring(0, 40) : f; this.task = null; }
    else if (a.equals("lprev") || a.equals("lnext")) {
      @PKG@.QLine[] ls = @PKG@.QDefs.LINES;
      int k = -1;
      for (int i = 0; i < ls.length; i++) if (ls[i].id.equals(this.line)) k = i;
      if (ls.length > 0) this.line = ls[(k < 0 ? 0 : k + (a.equals("lnext") ? 1 : ls.length - 1)) % ls.length].id;
      this.task = null;
    }
    else if (a.equals("prev") || a.equals("next")) { }
    else if (a.startsWith("skip:")) {                                   // line.task (also a bare task id)
      String k = a.substring(5);
      this.info = @PKG@.QEng.action(u, "skip", k);
      int d = k.indexOf('.');
      if (d > 0) { this.line = k.substring(0, d); this.task = k.substring(d + 1); } else this.task = k;
    }
    else if (a.equals("skip")) this.info = (this.line == null || this.task == null) ? "=Pick a task first." : @PKG@.QEng.action(u, "skip", this.line + "." + this.task);
    else if (a.equals("claim1")) this.info = (this.line == null || this.task == null) ? "=Pick a task first." : @PKG@.QEng.claimTask(u, this.line, this.task);
    else if (a.equals("claim")) this.info = @PKG@.QEng.action(u, "claim", null);
    else if (a.equals("track")) {
      @PKG@.QState s = @PKG@.QEng.stateOf(@PKG@.QEng.player(u));
      if (s != null && this.line != null && this.line.equals(s.track)) this.info = @PKG@.QEng.action(u, "untrack", this.line);
      else this.info = @PKG@.QEng.action(u, "track", this.line == null ? "" : this.line);
    }
    else if (a.equals("hide") || a.equals("show")) this.info = @PKG@.QEng.action(u, a, null);
  } catch (Throwable t) { @PKG@.QLog.warn("quest page click " + a + " failed: " + t); this.info = "-Something went wrong (server log)."; }
  rebuild();
}""")
# the World hub's Quests tab (HUBS-CONTRACT 1): apply(UUID) on the player's world thread (a hub click is the caller) opens this page;
