C(hopen, "public QHubOpen() { super(); }")
M(hopen, r"""
public Object apply(Object o) {
  if (!(o instanceof java.util.UUID)) return Boolean.FALSE;
  try {
    @PR@ pr = @UNI@.get().getPlayer((java.util.UUID) o);
    if (pr == null || !pr.isValid()) return Boolean.FALSE;
    @REF@ r = pr.getReference();
    if (r == null || !r.isValid()) return Boolean.FALSE;
    @ST@ st = r.getStore();
    if (st == null) return Boolean.FALSE;
    @PLA@ pl = (@PLA@) st.getComponent(r, @PLA@.getComponentType());
    if (pl == null) return Boolean.FALSE;
    pl.getPageManager().openCustomPage(r, st, new @PKG@.QLogPage(pr, null));
    OPENED = OPENED + 1L;
    return Boolean.TRUE;
  } catch (Throwable t) {
    @PKG@.QLog.warnOnce("hubopen", "the World > Quests tab could not open the page (logged once): " + t);
    return Boolean.FALSE;
  }
}""")
M(hopen, r"""
public static String register() {
  try {
    if (@PKG@.HubBar.put("%s", "%s", "SkyyQuests", "%s", %d, "%s", new @PKG@.QHubOpen(), null) != null) return "%s:%s";
  } catch (Throwable t) { @PKG@.QLog.warn("the World > Quests tab could not be registered: " + t); }
  return "off";
}""" % (Q_HUB, Q_TAB, Q_LABEL, Q_ORDER, Q_CMD, Q_HUB, Q_TAB))
M(hopen, r"""
public static int unregister() {
  try { return @PKG@.HubBar.removeAll(); } catch (Throwable t) { return 0; }
}""")

