# 0.4.3: /quests widget <hide | show | fold> -> SkyyHud 0.3.35's hud:fn:questFold (the Quest Tracker widget lives in SkyyHud). The answer
# line ("+" ok, "-" refused) for QCmdUtil.say; fold = "toggle" (open <-> folded), then "state" names what it is now
M(cu, r"""
public static String widget(java.util.UUID u, String a) {
  String w = a == null ? "" : a.trim().toLowerCase(java.util.Locale.ROOT);
  String op = w.equals("fold") ? "toggle" : ((w.equals("hide") || w.equals("show")) ? w : null);
  if (op == null) return "-Use /quests widget hide, /quests widget show or /quests widget fold.";
  java.util.function.Function f = @PKG@.QLog.fn("hud:fn:questFold");
  if (f == null) return "-The quest widget lives in SkyyHud - this needs SkyyHud 0.3.35 or newer.";
  Object r = null;
  if (op.equals("toggle")) {   // fix pass 2: SkyyHud must answer "state" (else it is stopping / has no layout); a hidden tracker = "show"
    Object s0 = null;
    try { s0 = f.apply(new Object[] { u, "state" }); } catch (Throwable t) { s0 = null; }
    if (!(s0 instanceof String)) return "-Your quest widget could not change right now.";
    if ("hidden".equals(s0)) op = "show";
  }
  try { r = f.apply(new Object[] { u, op }); } catch (Throwable t) { r = null; }
  if (!Boolean.TRUE.equals(r) && op.equals("toggle") && r != null) return "-No quest is on your tracker to fold right now.";   // fix pass: SkyyHud's FALSE
  if (!Boolean.TRUE.equals(r)) return "-Your quest widget could not change right now.";
  if (op.equals("hide")) return "+Quest widget hidden. /quests widget show brings it back.";
  if (op.equals("show")) return "+Quest widget shown.";
  Object s = null;
  try { s = f.apply(new Object[] { u, "state" }); } catch (Throwable t) { s = null; }
  return "folded".equals(s) ? "+Quest widget folded. /quests widget fold opens it again." : "+Quest widget open.";
}""")


